REVOKE EXECUTE ON FUNCTION public.seed_org_defaults(uuid, text, text) FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------
-- ONBOARDING
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.slugify(p text)
RETURNS text LANGUAGE sql IMMUTABLE AS $$
  SELECT trim(both '-' from regexp_replace(lower(coalesce(p,'')), '[^a-z0-9]+', '-', 'g'));
$$;

-- Creates a business, seeds it, makes p_user its Admin and switches them into it.
CREATE OR REPLACE FUNCTION public.create_organization_for(p_user uuid, p_email text, p_business text, p_full_name text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_org uuid; v_slug text; v_role uuid; n int := 0;
BEGIN
  IF p_user IS NULL OR coalesce(trim(p_business),'') = '' THEN RAISE EXCEPTION 'Business name required'; END IF;
  v_slug := nullif(slugify(p_business), '');
  v_slug := coalesce(v_slug, 'business');
  WHILE EXISTS (SELECT 1 FROM organizations WHERE slug = v_slug || CASE WHEN n = 0 THEN '' ELSE '-' || n END) LOOP
    n := n + 1;
  END LOOP;
  IF n > 0 THEN v_slug := v_slug || '-' || n; END IF;

  INSERT INTO organizations (name, slug, created_by) VALUES (trim(p_business), v_slug, p_user) RETURNING id INTO v_org;
  PERFORM seed_org_defaults(v_org, trim(p_business), p_email);
  SELECT id INTO v_role FROM app_roles WHERE org_id = v_org AND name = 'Admin';
  INSERT INTO app_users (org_id, user_id, email, name, role_id)
  VALUES (v_org, p_user, lower(p_email), coalesce(nullif(trim(p_full_name),''), split_part(p_email,'@',1)), v_role);
  INSERT INTO profiles (user_id, full_name, active_org_id) VALUES (p_user, p_full_name, v_org)
  ON CONFLICT (user_id) DO UPDATE SET active_org_id = EXCLUDED.active_org_id,
        full_name = COALESCE(profiles.full_name, EXCLUDED.full_name);
  RETURN v_org;
END $$;
REVOKE EXECUTE ON FUNCTION public.create_organization_for(uuid, text, text, text) FROM PUBLIC, anon, authenticated;

-- A signed-in user adds another business they own
CREATE OR REPLACE FUNCTION public.create_organization(p_business text)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_email text := auth.jwt() ->> 'email'; v_name text;
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF;
  SELECT full_name INTO v_name FROM profiles WHERE user_id = auth.uid();
  RETURN create_organization_for(auth.uid(), v_email, p_business, v_name);
END $$;
REVOKE EXECUTE ON FUNCTION public.create_organization(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.create_organization(text) TO authenticated;

-- Accept an emailed invitation (email on the invite must match the signed-in user)
CREATE OR REPLACE FUNCTION public.accept_invitation(p_token uuid)
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE inv RECORD; v_email text := lower(auth.jwt() ->> 'email');
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Not signed in'; END IF;
  SELECT * INTO inv FROM invitations WHERE token = p_token;
  IF NOT FOUND OR inv.revoked_at IS NOT NULL THEN RAISE EXCEPTION 'Invitation not found'; END IF;
  IF inv.accepted_at IS NOT NULL THEN RAISE EXCEPTION 'Invitation already used'; END IF;
  IF inv.expires_at < now() THEN RAISE EXCEPTION 'Invitation expired'; END IF;
  IF lower(inv.email) <> v_email THEN RAISE EXCEPTION 'This invitation was sent to a different email address'; END IF;

  INSERT INTO app_users (org_id, user_id, email, name, role_id)
  VALUES (inv.org_id, auth.uid(), v_email, coalesce(nullif(inv.name,''), split_part(v_email,'@',1)), inv.role_id)
  ON CONFLICT (org_id, user_id) DO UPDATE SET is_active = true, role_id = EXCLUDED.role_id;
  UPDATE invitations SET accepted_at = now() WHERE id = inv.id;
  INSERT INTO profiles (user_id, full_name, active_org_id) VALUES (auth.uid(), inv.name, inv.org_id)
  ON CONFLICT (user_id) DO UPDATE SET active_org_id = inv.org_id;
  RETURN inv.org_id;
END $$;
REVOKE EXECUTE ON FUNCTION public.accept_invitation(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.accept_invitation(uuid) TO authenticated;

-- Invite details for the accept page (works before sign-in, reveals only what's needed)
CREATE OR REPLACE FUNCTION public.get_invitation(p_token uuid)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT jsonb_build_object('email', i.email, 'name', i.name, 'business', o.name,
         'valid', i.accepted_at IS NULL AND i.revoked_at IS NULL AND i.expires_at > now(),
         'has_account', EXISTS (SELECT 1 FROM auth.users u WHERE lower(u.email) = lower(i.email)))
    FROM invitations i JOIN organizations o ON o.id = i.org_id WHERE i.token = p_token;
$$;
GRANT EXECUTE ON FUNCTION public.get_invitation(uuid) TO anon, authenticated;

-- Everything the app needs after sign-in: who am I, which business, my permissions, my other businesses
CREATE OR REPLACE FUNCTION public.get_my_context()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_org uuid := current_org_id(); r jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NULL; END IF;
  SELECT jsonb_build_object(
    'user_id', auth.uid(),
    'email', auth.jwt() ->> 'email',
    'org', (SELECT jsonb_build_object('id', o.id, 'name', o.name, 'slug', o.slug, 'timezone', o.timezone, 'plan', o.plan)
              FROM organizations o WHERE o.id = v_org),
    'member', (SELECT jsonb_build_object('id', u.id, 'name', u.name, 'role_id', u.role_id, 'role', to_jsonb(rl))
                 FROM app_users u LEFT JOIN app_roles rl ON rl.id = u.role_id
                WHERE u.org_id = v_org AND u.user_id = auth.uid()),
    'orgs', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name) ORDER BY o.name)
                        FROM app_users u JOIN organizations o ON o.id = u.org_id
                       WHERE u.user_id = auth.uid() AND u.is_active), '[]'::jsonb)
  ) INTO r;
  UPDATE app_users SET last_login = now() WHERE org_id = v_org AND user_id = auth.uid();
  RETURN r;
END $$;
REVOKE EXECUTE ON FUNCTION public.get_my_context() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_my_context() TO authenticated;

CREATE OR REPLACE FUNCTION public.switch_organization(p_org uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM app_users WHERE user_id = auth.uid() AND org_id = p_org AND is_active) THEN
    RAISE EXCEPTION 'Not a member of that business';
  END IF;
  INSERT INTO profiles (user_id, active_org_id) VALUES (auth.uid(), p_org)
  ON CONFLICT (user_id) DO UPDATE SET active_org_id = p_org;
END $$;
REVOKE EXECUTE ON FUNCTION public.switch_organization(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.switch_organization(uuid) TO authenticated;

-- Helper functions are internal
REVOKE EXECUTE ON FUNCTION public.fill_org_id() FROM PUBLIC, anon, authenticated;

-- ---------------------------------------------------------------------
-- STORAGE: one public bucket; writes only inside your org's folder
-- ---------------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public) VALUES ('Uploads', 'Uploads', true)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "org folder insert" ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (bucket_id = 'Uploads' AND (storage.foldername(name))[1] = (SELECT current_org_id())::text);
CREATE POLICY "org folder update" ON storage.objects FOR UPDATE TO authenticated
  USING (bucket_id = 'Uploads' AND (storage.foldername(name))[1] = (SELECT current_org_id())::text);
CREATE POLICY "org folder delete" ON storage.objects FOR DELETE TO authenticated
  USING (bucket_id = 'Uploads' AND (storage.foldername(name))[1] = (SELECT current_org_id())::text);
CREATE POLICY "org folder read" ON storage.objects FOR SELECT TO authenticated
  USING (bucket_id = 'Uploads' AND (storage.foldername(name))[1] = (SELECT current_org_id())::text);


-- ######## 04-stripe-connect.sql ########

-- =====================================================================
-- YOURCRM — part 4: Stripe Connect (each business = connected account)
-- =====================================================================
SET search_path = public, extensions;

ALTER TABLE public.organizations
  ADD COLUMN IF NOT EXISTS stripe_account_id text UNIQUE,
  ADD COLUMN IF NOT EXISTS stripe_charges_enabled boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS stripe_details_submitted boolean NOT NULL DEFAULT false,
  ADD COLUMN IF NOT EXISTS stripe_connected_at timestamptz;

-- Browsers may rename their business / change timezone, but the Stripe link
-- is only ever written by server functions (service role).
REVOKE UPDATE ON public.organizations FROM authenticated, anon;
GRANT UPDATE (name, timezone) ON public.organizations TO authenticated;

-- Surface payment readiness to the app
CREATE OR REPLACE FUNCTION public.get_my_context()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_org uuid := current_org_id(); r jsonb;
BEGIN
  IF auth.uid() IS NULL THEN RETURN NULL; END IF;
  SELECT jsonb_build_object(
    'user_id', auth.uid(),
    'email', auth.jwt() ->> 'email',
    'org', (SELECT jsonb_build_object('id', o.id, 'name', o.name, 'slug', o.slug, 'timezone', o.timezone, 'plan', o.plan,
                   'payments_enabled', (o.stripe_account_id IS NOT NULL AND o.stripe_charges_enabled))
              FROM organizations o WHERE o.id = v_org),
    'member', (SELECT jsonb_build_object('id', u.id, 'name', u.name, 'role_id', u.role_id, 'role', to_jsonb(rl))
                 FROM app_users u LEFT JOIN app_roles rl ON rl.id = u.role_id
                WHERE u.org_id = v_org AND u.user_id = auth.uid()),
    'orgs', COALESCE((SELECT jsonb_agg(jsonb_build_object('id', o.id, 'name', o.name) ORDER BY o.name)
                        FROM app_users u JOIN organizations o ON o.id = u.org_id
                       WHERE u.user_id = auth.uid() AND u.is_active), '[]'::jsonb)
  ) INTO r;
  UPDATE app_users SET last_login = now() WHERE org_id = v_org AND user_id = auth.uid();
  RETURN r;
END $$;


-- ######## 05-document-quotes.sql ########

-- =====================================================================
-- YOURCRM — part 5: "Attached document" quotes & invoices
-- A quote/invoice can be itemized (line items) or an uploaded document
-- (PDF/image) with a manually entered total. Deposits, payment schedules,
-- payment links, portal and Stripe all work off that total.
-- =====================================================================
SET search_path = public, extensions;

ALTER TABLE public.quotes
  ADD COLUMN IF NOT EXISTS document_mode text NOT NULL DEFAULT 'itemized'
    CHECK (document_mode IN ('itemized','attachment')),
  ADD COLUMN IF NOT EXISTS manual_total numeric(10,2);

ALTER TABLE public.invoices
  ADD COLUMN IF NOT EXISTS document_mode text NOT NULL DEFAULT 'itemized'
    CHECK (document_mode IN ('itemized','attachment')),
  ADD COLUMN IF NOT EXISTS manual_total numeric(10,2);

-- Files attached to an invoice (mirrors quote_attachments)
CREATE TABLE IF NOT EXISTS public.invoice_attachments (
  id uuid PRIMARY KEY DEFAULT uuid_generate_v4(),
  org_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
  invoice_id uuid NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,
  file_url text NOT NULL,
  file_name varchar(255) NOT NULL,
  file_type varchar(100),
  file_size integer,
  display_order integer DEFAULT 0,
  uploaded_at timestamptz DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_invoice_attachments_invoice ON public.invoice_attachments(invoice_id);
CREATE TRIGGER aa_fill_org_id BEFORE INSERT ON public.invoice_attachments
  FOR EACH ROW EXECUTE FUNCTION public.fill_org_id('invoice_id', 'invoices');
ALTER TABLE public.invoice_attachments ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON public.invoice_attachments FOR ALL TO authenticated
  USING (org_id = (SELECT current_org_id())) WITH CHECK (org_id = (SELECT current_org_id()));

-- ---------------------------------------------------------------------
-- Quotes: in attachment mode the manual total IS the total (tax included)
-- ---------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.apply_quote_manual_total()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.document_mode = 'attachment' THEN
    NEW.manual_total    := ROUND(GREATEST(COALESCE(NEW.manual_total, 0), 0), 2);
    NEW.subtotal        := NEW.manual_total;
    NEW.subtotal_low    := NULL;
    NEW.subtotal_high   := NULL;
    NEW.total_low       := NULL;
    NEW.total_high      := NULL;
    NEW.tax_rate        := 0;
    NEW.tax_amount      := 0;
    NEW.discount_value  := 0;
    NEW.discount_amount := 0;
    NEW.total           := NEW.manual_total;
    NEW.packages_enabled := false;
    NEW.deposit_amount  := CASE WHEN NEW.deposit_type = 'fixed' THEN LEAST(COALESCE(NEW.deposit_value, 0), NEW.manual_total)
                                ELSE ROUND(NEW.manual_total * COALESCE(NEW.deposit_value, 0) / 100, 2) END;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER ac_apply_quote_manual_total BEFORE INSERT OR UPDATE ON public.quotes
  FOR EACH ROW EXECUTE FUNCTION apply_quote_manual_total();

-- Line-item recalculation must not overwrite a manual total
CREATE OR REPLACE FUNCTION public.update_quote_totals()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  q RECORD;
  s numeric(10,2); s_low numeric(10,2); s_high numeric(10,2);
  has_ranges boolean; dep numeric(10,2);
BEGIN
  SELECT * INTO q FROM quotes WHERE id = COALESCE(NEW.quote_id, OLD.quote_id);
  IF q IS NULL OR q.document_mode = 'attachment' THEN RETURN NEW; END IF;
  SELECT
    COALESCE(SUM(CASE WHEN NOT is_optional OR is_selected THEN line_total ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN NOT is_optional OR is_selected THEN COALESCE(line_total_low, line_total) ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN NOT is_optional OR is_selected THEN COALESCE(line_total_high, line_total) ELSE 0 END), 0),
    BOOL_OR(is_range_pricing)
  INTO s, s_low, s_high, has_ranges
  FROM quote_line_items WHERE quote_id = q.id;

  IF q.deposit_type = 'percentage' THEN dep := s_low * (q.deposit_value / 100);
  ELSE dep := q.deposit_value; END IF;

  UPDATE quotes SET
    subtotal = s,
    subtotal_low = CASE WHEN has_ranges THEN s_low END,
    subtotal_high = CASE WHEN has_ranges THEN s_high END,
    tax_amount = s * q.tax_rate,
    total = s + s * q.tax_rate,
    total_low = CASE WHEN has_ranges THEN s_low + s_low * q.tax_rate END,
    total_high = CASE WHEN has_ranges THEN s_high + s_high * q.tax_rate END,
    deposit_amount = dep,
    updated_at = now()
  WHERE id = q.id;
  RETURN NEW;
END $$;

-- ---------------------------------------------------------------------
-- Invoices
-- ---------------------------------------------------------------------
-- An invoice created from an attachment-mode quote inherits the mode + total
CREATE OR REPLACE FUNCTION public.inherit_invoice_document_mode()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE q RECORD;
BEGIN
  IF NEW.quote_id IS NOT NULL AND COALESCE(NEW.document_mode, 'itemized') = 'itemized' AND NEW.manual_total IS NULL THEN
    SELECT document_mode, manual_total INTO q FROM quotes WHERE id = NEW.quote_id;
    IF q.document_mode = 'attachment' THEN
      NEW.document_mode := 'attachment';
      NEW.manual_total := q.manual_total;
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER ab_inherit_invoice_document_mode BEFORE INSERT ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION inherit_invoice_document_mode();

CREATE OR REPLACE FUNCTION public.apply_invoice_manual_total()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.document_mode = 'attachment' THEN
    NEW.manual_total    := ROUND(GREATEST(COALESCE(NEW.manual_total, 0), 0), 2);
    NEW.subtotal        := NEW.manual_total;
    NEW.tax_rate        := 0;
    NEW.tax_amount      := 0;
    NEW.discount_value  := 0;
    NEW.discount_amount := 0;
    NEW.total           := NEW.manual_total;
    NEW.amount_due      := NEW.manual_total - COALESCE(NEW.amount_paid, 0);
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER ac_apply_invoice_manual_total BEFORE INSERT OR UPDATE ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION apply_invoice_manual_total();

-- Copy the quote's document(s) onto the new invoice
CREATE OR REPLACE FUNCTION public.copy_quote_attachments_to_invoice()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.document_mode = 'attachment' AND NEW.quote_id IS NOT NULL THEN
    INSERT INTO invoice_attachments (org_id, invoice_id, file_url, file_name, file_type, file_size, display_order)
    SELECT NEW.org_id, NEW.id, file_url, file_name, file_type, file_size, display_order
      FROM quote_attachments WHERE quote_id = NEW.quote_id;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER trg_copy_quote_attachments_to_invoice AFTER INSERT ON public.invoices
  FOR EACH ROW EXECUTE FUNCTION copy_quote_attachments_to_invoice();

-- Line-item recalculation must not overwrite a manual total
CREATE OR REPLACE FUNCTION public.update_invoice_totals()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  inv RECORD;
  c_sub numeric(10,2); c_tax_base numeric(10,2); c_disc_base numeric(10,2); c_tax_disc numeric(10,2);
  c_disc numeric(10,2); share numeric; c_tax numeric(10,2); c_total numeric(10,2);
BEGIN
  SELECT * INTO inv FROM invoices WHERE id = COALESCE(NEW.invoice_id, OLD.invoice_id);
  IF inv IS NULL OR inv.document_mode = 'attachment' THEN RETURN NEW; END IF;
  SELECT COALESCE(SUM(line_total),0),
         COALESCE(SUM(line_total) FILTER (WHERE is_taxable),0),
         COALESCE(SUM(line_total) FILTER (WHERE apply_discount IS DISTINCT FROM false),0),
         COALESCE(SUM(line_total) FILTER (WHERE is_taxable AND apply_discount IS DISTINCT FROM false),0)
    INTO c_sub, c_tax_base, c_disc_base, c_tax_disc
    FROM invoice_line_items WHERE invoice_id = inv.id;

  IF inv.discount_type = 'fixed' THEN c_disc := LEAST(COALESCE(inv.discount_value,0), c_disc_base);
  ELSE c_disc := c_disc_base * COALESCE(inv.discount_value,0) / 100; END IF;
  c_disc := ROUND(GREATEST(c_disc, 0), 2);
  share := CASE WHEN c_disc_base > 0 THEN c_tax_disc / c_disc_base ELSE 0 END;
  c_tax := GREATEST(0, c_tax_base - c_disc * share) * COALESCE(inv.tax_rate, 0);
  c_total := c_sub - c_disc + c_tax;

  UPDATE invoices SET subtotal = c_sub, discount_amount = c_disc, tax_amount = c_tax,
         total = c_total, amount_due = c_total - amount_paid, updated_at = now()
   WHERE id = inv.id;
  RETURN NEW;
END $$;


